options.customCss:
:root {
  /* 🌸 Pastel Colors */
  --chat--color--primary: #f8a5c2;           /* pastel pink */
  --chat--color--primary-shade-50: #f39ab9;
  --chat--color--primary--shade-100: #ec8fb0;

  --chat--color--secondary: #7ed6c1;         /* pastel mint */
  --chat--color-secondary-shade-50: #6bcbb4;

  --chat--color-white: #ffffff;
  --chat--color-light: #fdf6f9;              /* soft background */
  --chat--color-light-shade-50: #f6e9ef;
  --chat--color-light-shade-100: #e9dbe3;

  --chat--color-medium: #e6dfe5;
  --chat--color-dark: #5a5a6e;
  --chat--color-disabled: #e0d8df;
  --chat--color-typing: #7a7a8c;

  /* Layout */
  --chat--spacing: 1rem;
  --chat--border-radius: 1rem;
  --chat--transition-duration: 0.2s;
  --chat--font-family: 'Segoe UI', sans-serif;

  /* Window */
  --chat--window--width: 380px;
  --chat--window--height: 580px;
  --chat--window--border-radius: 1.2rem;
  --chat--window--border: none;
  --chat--window--z-index: 9999;

  /* Header */
  --chat--header--background: linear-gradient(135deg,#f8a5c2,#c7ceea);
  --chat--header--color: white;
  --chat--header--padding: 1.2rem;

  --chat--heading--font-size: 1.3rem;

  /* Message */
  --chat--message--font-size: 0.95rem;
  --chat--message--padding: 0.8rem 1rem;
  --chat--message--border-radius: 1rem;
  --chat--message--margin-bottom: 0.7rem;

  --chat--message--bot--background: #ffffff;
  --chat--message--bot--color: #5a5a6e;

  --chat--message--user--background: #7ed6c1;
  --chat--message--user--color: white;

  --chat--message--pre--background: #f4f4f8;

  /* Toggle button */
  --chat--toggle--size: 60px;
  --chat--toggle--background: linear-gradient(135deg,#f8a5c2,#c7ceea);
  --chat--toggle--hover--background: #f39ab9;
  --chat--toggle--active--background: #ec8fb0;
  --chat--toggle--color: white;

  /* Input */
  --chat--textarea--height: 48px;
  --chat--input--background: white;
  --chat--input--border-radius: 1rem;
  --chat--input--padding: 0.7rem;
  --chat--input--text-color: #5a5a6e;

  /* Button */
  --chat--button--border-radius: 0.8rem;

  --chat--button--background--primary: #7ed6c1;
  --chat--button--background--primary--hover: #6bcbb4;

  --chat--button--background--secondary: #c7ceea;
  --chat--button--background--secondary--hover: #b5bde0;

  /* Send icon */
  --chat--input--send--button--color: #7ed6c1;
  --chat--input--send--button--color-hover: #f8a5c2;

  /* Background */
  --chat--body--background: #fdf6f9;
  --chat--footer--background: #fdf6f9;
}

/* Bubble style lebih aesthetic */
.chat-message {
  max-width: 70%;
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

/* smooth animation */
.chat-window {
  backdrop-filter: blur(6px);
}
